// Package tutorial_templates embeds the static reveal.js tutorial bundle
// exported from docs/onboarding/mdemg-onboarding-deck.md so `/ui/tutorial/`
// can serve the operator-facing onboarding tutorial with zero runtime
// dependencies. ONBOARDING-TUTORIAL-SERVE-001.
//
// Source-of-truth is `docs/onboarding/mdemg-onboarding-deck.md` at the
// repo root. The exported bundle lives in `staged/` (regenerated by
// `make sync-tutorial-embed`, which runs `node scripts/tutorial/export.mjs`).
// Because //go:embed can't cross package boundaries or use `..`, we mirror
// the exported tree into `staged/` and keep the two in sync via a Makefile
// target + CI drift check (`make verify-tutorial-embed`). Editing the deck
// source without re-running the sync FAILS CI at the drift check.
//
// Unlike grafana_templates (which materializes to the operator's cwd for
// `mdemg init`), this embed is served directly from the handler via
// http.FS(FS()); nothing is written to disk at runtime.
package tutorial_templates

import (
	"bufio"
	"embed"
	"fmt"
	"io/fs"
	"strings"
)

// embedded is the raw go:embed tree. Private — callers use FS()/StagedFS()
// which strip the staged/ prefix so URLs/paths are clean.
//
//go:embed all:staged
var embedded embed.FS

// StagedRoot is the in-embed root directory. Matches the go:embed target.
const StagedRoot = "staged"

// FS returns the embedded tutorial tree rooted at `staged/` with the prefix
// stripped. Serves as an http.FileSystem via http.FS(FS()). An HTTP
// handler mounting at /ui/tutorial/ should strip that prefix before dispatch;
// requests then land at paths like "index.html", "dist/reveal.css", etc.
//
// Returns an error only if the embed is empty (build-time misconfiguration),
// which the handler should treat as a 503.
func FS() (fs.FS, error) {
	sub, err := fs.Sub(embedded, StagedRoot)
	if err != nil {
		return nil, fmt.Errorf("tutorial_templates: fs.Sub(%q): %w", StagedRoot, err)
	}
	// Smoke check: index.html MUST be present or the build pipeline failed.
	if _, sErr := fs.Stat(sub, "index.html"); sErr != nil {
		return nil, fmt.Errorf("tutorial_templates: index.html missing from embed — re-run `make sync-tutorial-embed`: %w", sErr)
	}
	return sub, nil
}

// Manifest returns the list of embedded file paths (relative to StagedRoot).
// Exposed for tests + CI drift verification.
func Manifest() ([]string, error) {
	var out []string
	err := fs.WalkDir(embedded, StagedRoot, func(path string, d fs.DirEntry, wErr error) error {
		if wErr != nil {
			return wErr
		}
		if d.IsDir() {
			return nil
		}
		out = append(out, strings.TrimPrefix(path, StagedRoot+"/"))
		return nil
	})
	return out, err
}

// SourceSHA parses the SOURCE_SHA256.txt breadcrumb written by the export
// script. Returns (deckSHA, cssSHA) — the sha256 of the source files at
// export time. Used by `scripts/verify_tutorial_embed.py` (CI drift gate) to
// detect "deck source edited without re-running the sync."
func SourceSHA() (deckSHA, cssSHA string, err error) {
	f, oErr := embedded.Open(StagedRoot + "/SOURCE_SHA256.txt")
	if oErr != nil {
		return "", "", fmt.Errorf("tutorial_templates: open SOURCE_SHA256.txt: %w", oErr)
	}
	defer func() { _ = f.Close() }()
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if v, ok := strings.CutPrefix(line, "deck_sha256="); ok {
			deckSHA = v
		}
		if v, ok := strings.CutPrefix(line, "css_sha256="); ok {
			cssSHA = v
		}
	}
	if sErr := scanner.Err(); sErr != nil {
		return "", "", fmt.Errorf("tutorial_templates: scan SOURCE_SHA256.txt: %w", sErr)
	}
	if deckSHA == "" || cssSHA == "" {
		return "", "", fmt.Errorf("tutorial_templates: SOURCE_SHA256.txt missing deck_sha256 or css_sha256 — re-run `make sync-tutorial-embed`")
	}
	return deckSHA, cssSHA, nil
}

// EmbedSize returns the total byte count of all embedded files. Exposed
// for the boot-log + sprint-post metrics; not called on the hot path.
func EmbedSize() (int64, error) {
	var total int64
	err := fs.WalkDir(embedded, StagedRoot, func(path string, d fs.DirEntry, wErr error) error {
		if wErr != nil {
			return wErr
		}
		if d.IsDir() {
			return nil
		}
		info, iErr := d.Info()
		if iErr != nil {
			return iErr
		}
		total += info.Size()
		return nil
	})
	return total, err
}

